{
  "code": "const clean = (input: string): string => {
  if (input === undefined || input === "NaN" || input === "Infinity") return input;
  input = input.replace(/[\s\(\)]+/g, "");
  input = input.replace(/-/, "");
  input = input.replace(/\+1/, "");
  if (input.length !== 10) return input;
  return input;
};
export { clean };"
}

